async function execute(inputs, context) {
  const { scriptInput, generatorRules } = inputs;
  const errors = [];
  let input = typeof scriptInput === 'string' ? JSON.parse(scriptInput) : scriptInput;
  let rules = typeof generatorRules === 'string' ? JSON.parse(generatorRules) : generatorRules;
  rules = { requireDialogueForNarrativeKinds: true, requireHeadshotForEachNamedCharacter: true, requireLandscapeForEachLocation: true, requirePrevisForEveryShot: true, ...rules };
  const validKinds = ['commercial', 'tv-episode', 'tv-pilot', 'feature-film', 'short-film'];
  if (!input.kind || !validKinds.includes(input.kind)) errors.push('Invalid kind: ' + input.kind);
  if (!input.title) errors.push('Missing required field: title');
  if (!input.genre) errors.push('Missing required field: genre');
  if (!input.visualizationStyle) errors.push('Missing required field: visualizationStyle');
  const normalizeArray = (val) => Array.isArray(val) ? val : (val ? [val] : []);
  const validatedInput = {
    kind: input.kind,
    title: input.title || 'Untitled',
    subtitle: input.subtitle || null,
    genre: normalizeArray(input.genre),
    visualizationStyle: input.visualizationStyle || 'cinematic',
    logline: input.logline || null,
    tone: normalizeArray(input.tone),
    audience: normalizeArray(input.audience),
    language: input.language || 'en',
    runtimeMinutes: input.runtimeMinutes || (input.kind === 'commercial' ? 0.5 : input.kind === 'short-film' ? 15 : 90),
    author: input.author || [{ name: 'Unknown', role: 'writer' }]
  };
  if (['tv-episode', 'tv-pilot'].includes(input.kind)) {
    validatedInput.series = input.series ? { seriesTitle: input.series.seriesTitle || input.title, seasonNumber: input.series.seasonNumber || 1, episodeNumber: input.series.episodeNumber || 1, episodeTitle: input.series.episodeTitle || input.title, arcSummary: input.series.arcSummary || null } : { seriesTitle: input.title, seasonNumber: 1, episodeNumber: 1, episodeTitle: input.title, arcSummary: null };
  }
  if (input.kind === 'commercial') {
    validatedInput.commercial = input.commercial ? { brand: input.commercial.brand || null, product: input.commercial.product || null, campaign: input.commercial.campaign || null, spotLengthSeconds: input.commercial.spotLengthSeconds || 30, aspectRatio: input.commercial.aspectRatio || '16:9', callToAction: input.commercial.callToAction || null, deliverables: input.commercial.deliverables || [] } : { brand: null, product: null, campaign: null, spotLengthSeconds: 30, aspectRatio: '16:9', callToAction: null, deliverables: [] };
  }
  context.log('Validated input for ' + validatedInput.kind + ': ' + validatedInput.title);
  return { validatedInput, rules, errors };
}
